glsl:
vec4 effect(vec2 uv) {
  vec4 c = getColor(uv);
  vec2 g = vec2(120.0 * uRatio, 120.0);
  vec2 id = floor(uv * g);
  float h = hash(id);
  float tw = 0.5 + 0.5 * sin(uTime * 3.0 + h * 40.0);
  float star = step(0.993, h) * smoothstep(0.5, 0.0, length(fract(uv * g) - 0.5)) * tw;
  float dark = 1.0 - smoothstep(0.25, 0.6, luma(c.rgb));
  return vec4(c.rgb + vec3(star * dark * 1.5 * uAmount), c.a);
}
